CREATE COLUMN TABLE "TEST_AP"."OCSN" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(4) NOT NULL , "Section" INTEGER CS_INT, "Location" INTEGER CS_INT, "DfltSeries" SMALLINT CS_INT DEFAULT 0, PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCSN_CODE" ON "TEST_AP"."OCSN" ( "Code" ASC );
CREATE INDEX "OCSN_SECTION" ON "TEST_AP"."OCSN" ( "Section" ASC );
CREATE INDEX "OCSN_LOCATION" ON "TEST_AP"."OCSN" ( "Location" ASC )